const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, did you manage to read the tutor feedback on our history poster assignment yet?","position":1,"audioStartSeconds":0,"audioEndSeconds":5.752416666666667},{"speaker":"B","text":"Yes, I read it this morning although the comments were quite critical about our visual layout.","position":2,"audioStartSeconds":5.952416666666666,"audioEndSeconds":11.7935},{"speaker":"A","text":"I was surprised because we spent so much time organizing the paragraphs and headings.","position":3,"audioStartSeconds":11.9935,"audioEndSeconds":17.355083333333333},{"speaker":"B","text":"The tutor felt that the text blocks were too dense and difficult to read from a distance.","position":4,"audioStartSeconds":17.555083333333332,"audioEndSeconds":22.542958333333335},{"speaker":"A","text":"If we make the font larger and reduce the word count, viewers will understand it much faster.","position":5,"audioStartSeconds":22.742958333333334,"audioEndSeconds":28.567708333333332},{"speaker":"B","text":"We could also replace some descriptive paragraphs with simple bullet points to save space.","position":6,"audioStartSeconds":28.767708333333335,"audioEndSeconds":34.3605},{"speaker":"A","text":"That sounds like a sensible strategy because dense paragraphs always overwhelm readers.","position":7,"audioStartSeconds":34.5605,"audioEndSeconds":40.06308333333333},{"speaker":"B","text":"What about the color scheme since the tutor suggested changing our dark background?","position":8,"audioStartSeconds":40.263083333333334,"audioEndSeconds":45.366166666666665},{"speaker":"A","text":"She recommended using a light neutral background when we presented historical statistics.","position":9,"audioStartSeconds":45.56616666666667,"audioEndSeconds":51.28783333333333},{"speaker":"B","text":"I initially thought about adding bright neon colors to attract more attention from students.","position":10,"audioStartSeconds":51.487833333333334,"audioEndSeconds":57.04195833333333},{"speaker":"A","text":"Neon colours might look unprofessional, so a clean white background is safer.","position":11,"audioStartSeconds":57.241958333333336,"audioEndSeconds":62.26770833333333},{"speaker":"B","text":"You are completely right, and we must fix these issues before submission tomorrow.","position":12,"audioStartSeconds":62.467708333333334,"audioEndSeconds":67.58370833333333},{"speaker":"A","text":"Let us divide the tasks so that you edit the text and I update the background.","position":13,"audioStartSeconds":67.78370833333334,"audioEndSeconds":72.83133333333333},{"speaker":"B","text":"That division of labor works well for me, so let us start working immediately.","position":14,"audioStartSeconds":73.03133333333334,"audioEndSeconds":78.07916666666667}],"questions":[{"prompt":"What is the main purpose of the conversation?","options":["To review tutor feedback and plan poster improvements.","To complain about unfair grading from the history tutor.","To decide who will present the poster to the class."],"answer":"A","evidenceSentence":1,"evidence":"did you manage to read the tutor feedback on our history poster assignment yet","explanation":"Hai sinh viên thảo luận về phản hồi của gia sư và lên kế hoạch cải thiện tấm poster."},{"prompt":"What did the tutor criticize about the original poster layout?","options":["The historical dates were incorrect.","The text blocks were too dense.","The poster lacked any headings."],"answer":"B","evidenceSentence":4,"evidence":"The tutor felt that the text blocks were too dense","explanation":"Gia sư nhận xét các khối văn bản quá dày đặc và khó đọc từ xa."},{"prompt":"How do the students plan to handle the lengthy text?","options":["By deleting half of the research topics.","By recording an audio file to accompany it.","By using larger fonts and bullet points."],"answer":"C","evidenceSentence":6,"evidence":"We could also replace some descriptive paragraphs with simple bullet points","explanation":"Họ quyết định dùng phông chữ lớn hơn và thay thế đoạn văn bằng các gạch đầu dòng."},{"prompt":"What color scheme did the tutor recommend for the background?","options":["A light neutral background.","A bright neon background.","A dark professional background."],"answer":"A","evidenceSentence":9,"evidence":"She recommended using a light neutral background","explanation":"Gia sư đề xuất sử dụng nền màu sáng trung tính."},{"prompt":"What design idea did speaker B initially suggest and then abandon?","options":["Adding historical photographs.","Using bright neon colors.","Writing longer descriptive paragraphs."],"answer":"B","evidenceSentence":10,"evidence":"I initially thought about adding bright neon colors","explanation":"Người nói B ban đầu đề xuất dùng màu neon sáng nhưng sau đó đã loại bỏ."},{"prompt":"What will the students do next to finish the assignment?","options":["Ask the tutor for more advice.","Submit the poster without changes.","Divide the remaining editing tasks."],"answer":"C","evidenceSentence":13,"evidence":"Let us divide the tasks so that you edit the text and I update the background","explanation":"Họ quyết định chia nhau các công việc chỉnh sửa còn lại trước khi nộp."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
